#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\xampp\htdocs\gs_cns\node_modules\.pnpm\@google+clasp@2.5.0_@types+node@26.6.6_supports-color@7.2.0\node_modules\@google\clasp\node_modules;D:\xampp\htdocs\gs_cns\node_modules\.pnpm\@google+clasp@2.5.0_@types+node@26.6.6_supports-color@7.2.0\node_modules;D:\xampp\htdocs\gs_cns\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/d/xampp/htdocs/gs_cns/node_modules/.pnpm/@google+clasp@2.5.0_@types+node@26.6.6_supports-color@7.2.0/node_modules/@google/clasp/node_modules:/mnt/d/xampp/htdocs/gs_cns/node_modules/.pnpm/@google+clasp@2.5.0_@types+node@26.6.6_supports-color@7.2.0/node_modules:/mnt/d/xampp/htdocs/gs_cns/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../@google/clasp/build/src/index.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../@google/clasp/build/src/index.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../@google/clasp/build/src/index.js" $args
  } else {
    & "node$exe"  "$basedir/../@google/clasp/build/src/index.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
